mapper.select:
SELECT r.id, r.name, r.credit_code AS creditCode, r.signing_entity AS signingEntity, r.contact_person AS contactPerson, r.contact_phone AS contactPhone, r.cooperation_status AS cooperationStatus, r.status, r.business_entity_id AS businessEntityId, r.remark, r.create_time AS createTime, be.name AS businessEntityName FROM ad_upstream_agent r LEFT JOIN ad_business_entity be ON be.id = r.business_entity_id AND be.deleted = 0 WHERE r.deleted = 0 AND r.organization_id = #{request.organizationId}
AND r.name LIKE CONCAT('%', #{request.keyword}, '%')
AND r.cooperation_status = #{request.cooperationStatus}
AND r.status = #{request.status}
AND r.business_entity_id = #{request.businessEntityId}
AND r.business_entity_id IN
#{eid}
ORDER BY r.create_time DESC
